pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;

    function setUp() public { c = new Wallet(); }

    function testFuzz_property(address actor, uint256 initialAmount) public {
        vm.assume(actor != address(0));
        initialAmount = bound(initialAmount, 1, type(uint128).max);

        vm.deal(actor, initialAmount);

        uint256 before = address(c).balance;

        vm.prank(actor);
        c.deposit{value: initialAmount}();

        uint256 afterDeposit = address(c).balance;

        bool ok;
        vm.prank(actor);
        try c.deposit{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
